commands.command:
/bin/bash -lc "cat > tests/transactional_accumulator.test.mjs <<'EOF'
import test from \"node:test\";
import assert from \"node:assert/strict\";
import { accumulate as domain } from \"../src/transactional_accumulator.ts\";
import { accumulate as api } from \"../src/api.ts\";

for (const [name, accumulate] of Object.entries({ domain, api })) {
  test("'`${name}: commits repeated and unknown keys and returns a detached snapshot`, () => {
    const state = { a: 2, untouched: 7 };
    const snapshot = accumulate(state, [
      { key: "a", amount: -2 },
      { key: "new", amount: 3 },
      { key: "new", amount: -1 },
    ]);
    assert.deepEqual(state, { a: 0, untouched: 7, new: 2 });
    assert.deepEqual(snapshot, state);
    assert.notStrictEqual(snapshot, state);
    snapshot.a = 99;
    state.new = 8;
    assert.equal(state.a, 0);
    assert.equal(snapshot.new, 2);
    assert.notStrictEqual(accumulate(state, []), state);
  });

  test(`${name}: invalid batches preserve all original state`, () => {
    for (const amount of [-1, 0.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1]) {
      const state = { a: 2 };
      assert.throws(() => accumulate(state, [
        { key: "a", amount: 1 },
        { key: "created", amount: 2 },
        { key: "bad", amount },
      ]));
      assert.deepEqual(state, { a: 2 });
    }
    const state = { a: Number.MAX_SAFE_INTEGER };
    assert.throws(() => accumulate(state, [{ key: "a", amount: 1 }]));
    assert.deepEqual(state, { a: Number.MAX_SAFE_INTEGER });
    assert.throws(() => accumulate(state, [
      { key: "new", amount: 1 }, { key: "new", amount: -2 },
    ]));
    assert.deepEqual(state, { a: Number.MAX_SAFE_INTEGER });
  });

  test(`${name}: prototype names are own counters and inherited balances are ignored`, () => {
    const state = Object.create({ inherited: 100 });
    const prototype = Object.getPrototypeOf(state);
    const snapshot = accumulate(state, [
      { key: "__proto__", amount: 3 },
      { key: "__proto__", amount: -1 },
      { key: "constructor", amount: 4 },
      { key: "inherited", amount: 1 },
    ]);
    assert.equal(Object.getPrototypeOf(state), prototype);
    for (const result of [state, snapshot]) {
      assert.equal(Object.hasOwn(result, "__proto__"), true);
      assert.equal(result.__proto__, 2);
      assert.equal(result.constructor, 4);
      assert.equal(result.inherited, 1);
    }
    assert.equal(Object.getPrototypeOf(snapshot), Object.prototype);
    assert.throws(() => accumulate(state, [
      { key: "__proto__", amount: 1 }, { key: "bad", amount: -1 },
    ]));
    assert.equal(state.__proto__, 2);
  });
}
EOF
node --test tests/*.test.mjs'
